    uint256 private count;
    bool private locked;

    event CounterIncremented(uint256 newValue);
    event CounterDecremented(uint256 newValue);

    modifier noReentrancy() {
        require(!locked, "Reentrancy detected");
        locked = true;
        _;
        locked = false;
    }

    constructor() {
        count = 0;
        locked = false;
    }

    /// @notice Increases the counter by 1
    function increment() external noReentrancy {
        count += 1;
        emit CounterIncremented(count);
    }

    /// @notice Decreases the counter by 1
    /// @dev Reverts if the counter is 0 to prevent underflow
    function decrement() external noReentrancy {
        require(count > 0, "Counter: cannot decrement below zero");
        count -= 1;
        emit CounterDecremented(count);
    }

    /// @notice Returns the current counter value
    /// @return The current count
    function getCount() external view returns (uint256) {
        return count;
    }
}

