    /// @notice Event emitted when an addition is performed
    event Addition(uint256 a, uint256 b, uint256 result);
    /// @notice Event emitted when a subtraction is performed
    event Subtraction(uint256 a, uint256 b, uint256 result);
    /// @notice Event emitted when a multiplication is performed
    event Multiplication(uint256 a, uint256 b, uint256 result);
    /// @notice Event emitted when a division is performed
    event Division(uint256 a, uint256 b, uint256 result);

    /// @notice Adds two numbers
    /// @param a First number
    /// @param b Second number
    /// @return result The sum of a and b
    function add(uint256 a, uint256 b) external returns (uint256 result) {
        result = a + b;
        emit Addition(a, b, result);
    }

    /// @notice Subtracts b from a
    /// @param a Minuend
    /// @param b Subtrahend
    /// @return result The difference of a and b
    function subtract(uint256 a, uint256 b) external returns (uint256 result) {
        require(a >= b, "Calculator: subtraction result would be negative");
        result = a - b;
        emit Subtraction(a, b, result);
    }

    /// @notice Multiplies two numbers
    /// @param a First number
    /// @param b Second number
    /// @return result The product of a and b
    function multiply(uint256 a, uint256 b) external returns (uint256 result) {
        result = a * b;
        emit Multiplication(a, b, result);
    }

    /// @notice Divides a by b
    /// @param a Dividend
    /// @param b Divisor
    /// @return result The quotient of a and b
    function divide(uint256 a, uint256 b) external returns (uint256 result) {
        require(b != 0, "Calculator: division by zero");
        result = a / b;
        emit Division(a, b, result);
    }
}

