    uint256[] private values;

    /// @notice Event emitted when a new value is added to the array
    event ValueAdded(uint256 value);

    /// @notice Appends a value to the array
    /// @param _value The value to be added
    function push(uint256 _value) external {
        values.push(_value);
        emit ValueAdded(_value);
    }

    /// @notice Returns the minimum value in the array
    /// @dev Reverts if the array is empty
    /// @return min The smallest value found
    function getMin() external view returns (uint256 min) {
        require(values.length > 0, "Array is empty");
        min = values[0];
        for (uint256 i = 1; i < values.length; i++) {
            if (values[i] < min) {
                min = values[i];
            }
        }
    }

    /// @notice Returns the maximum value in the array
    /// @dev Reverts if the array is empty
    /// @return max The largest value found
    function getMax() external view returns (uint256 max) {
        require(values.length > 0, "Array is empty");
        max = values[0];
        for (uint256 i = 1; i < values.length; i++) {
            if (values[i] > max) {
                max = values[i];
            }
        }
    }

    /// @notice Returns the number of elements in the array
    /// @return The length of the array
    function getLength() external view returns (uint256) {
        return values.length;
    }
}

