    mapping(address => string) private _names;
    mapping(address => bool) private _registered;

    /// @notice Emitted when a new name is registered
    event Registered(address indexed user, string name);

    /// @notice Emitted when a registration is removed
    event Unregistered(address indexed user);

    /// @notice Registers the caller with a specific name
    /// @param _name The name to associate with the sender's address
    function register(string calldata _name) external {
        require(bytes(_name).length > 0, "Name cannot be empty");
        _names[msg.sender] = _name;
        _registered[msg.sender] = true;
        emit Registered(msg.sender, _name);
    }

    /// @notice Returns the name associated with an address
    /// @param _addr The address to query
    /// @return The registered name
    function getName(address _addr) external view returns (string memory) {
        return _names[_addr];
    }

    /// @notice Checks if an address is registered
    /// @param _addr The address to check
    /// @return True if registered, false otherwise
    function isRegistered(address _addr) external view returns (bool) {
        return _registered[_addr];
    }

    /// @notice Removes the registration for the caller
    function unregister() external {
        require(_registered[msg.sender], "Address not registered");
        delete _names[msg.sender];
        delete _registered[msg.sender];
        emit Unregistered(msg.sender);
    }
}

