    event Deposit(address indexed sender, uint256 amount, uint256 unlockTime);
    event Withdrawal(address indexed sender, uint256 amount);

    modifier nonReentrant() {
        require(!locked, "Reentrancy detected");
        locked = true;
        _;
        locked = false;
    }

    constructor() {
        owner = msg.sender;
    }

    /// @notice Locks ETH until the specified unlockTime
    /// @param unlockTime The timestamp when the funds can be withdrawn
    function deposit(uint256 unlockTime) external payable {
        require(msg.value > 0, "Amount must be greater than 0");
        require(unlockTime > block.timestamp, "Unlock time must be in the future");
        require(locks[msg.sender].amount == 0, "Existing lock found, withdraw first");

        locks[msg.sender] = LockInfo({
            amount: msg.value,
            unlockTime: unlockTime
        });

        emit Deposit(msg.sender, msg.value, unlockTime);
    }

    /// @notice Withdraws all locked ETH if the unlock time has passed
    function withdraw() external nonReentrant {
        LockInfo storage userLock = locks[msg.sender];

        require(userLock.amount > 0, "No locked funds");
        require(block.timestamp >= userLock.unlockTime, "Funds are still locked");

        uint256 amountToWithdraw = userLock.amount;

        userLock.amount = 0;
        userLock.unlockTime = 0;

        (bool success, ) = payable(msg.sender).call{value: amountToWithdraw}("");
        require(success, "Transfer failed");

        emit Withdrawal(msg.sender, amountToWithdraw);
    }

