    address public seller;
    uint256 public endAt;
    bool public ended;

    address public highestBidder;
    uint256 public highestBid;

    mapping(address => uint256) public pendingReturns;

    event BidPlaced(address indexed bidder, uint256 amount);
    event AuctionEnded(address indexed winner, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == seller, "Not the seller");
        _;
    }

    constructor(uint256 startingBid, uint256 auctionDuration) {
        seller = msg.sender;
        highestBid = startingBid;
        endAt = block.timestamp + auctionDuration;
    }

    /// @notice Place a bid in the auction
    function bid() external payable {
        require(block.timestamp < endAt, "Auction expired");
        require(msg.value > highestBid, "Bid too low");

        if (highestBidder != address(0)) {
            pendingReturns[highestBidder] += highestBid;
        }

        highestBidder = msg.sender;
        highestBid = msg.value;

        emit BidPlaced(msg.sender, msg.value);
    }

    /// @notice Withdraw overbid funds
    function withdraw() external returns (bool) {
        uint256 amount = pendingReturns[msg.sender];
        if (amount > 0) {
            pendingReturns[msg.sender] = 0;
            (bool success, ) = payable(msg.sender).call{value: amount}("");
            require(success, "Transfer failed");
            return true;
        }
        return false;
    }

    /// @notice End the auction and transfer funds to seller
    function end() external onlyOwner {
        require(block.timestamp >= endAt, "Auction not yet ended");
        require(!ended, "Auction already ended");

        ended = true;

        (bool success, ) = payable(seller).call{value: highestBid}("");
        require(success, "Transfer to seller failed");

        emit AuctionEnded(highestBidder, highestBid);
    }

    function getSeller() external view returns (address) { return seller; }
    function getHighestBidder() external view returns (address) { return highestBidder; }
    function getHighestBid() external view returns (uint256) { return highestBid; }
    function getEnded() external view returns (bool) { return ended; }
    function getEndAt() external view returns (uint256) { return endAt; }
}

