    function _calculateRewards(address _addr) internal view returns (uint256) {
        StakeInfo storage s = stakes[_addr];
        if (s.amount == 0) return 0;
        uint256 timeElapsed = block.timestamp - s.lastUpdateTime;
        return s.pendingRewards + (s.amount * timeElapsed);
    }

